"""Write parts/hkrig.js (the rig data the app embeds) from hk/out/rig.json."""
import json, os, sys
HK = os.path.dirname(os.path.abspath(__file__))
src = sys.argv[1] if len(sys.argv) > 1 else os.path.join(HK, 'out', 'rig.json')
r = json.load(open(src))
keep = None
if len(sys.argv) > 2: keep = set(sys.argv[2].split(','))
av = {k: v for k, v in r['avatars'].items() if not keep or k in keep}
out = ('/* Rig data for the realistic people: joint positions (mm) of each Microsoft Rocketbox avatar\n'
       '   (MIT License, Copyright (c) 2020 Microsoft), generated by hk/build.mjs from commit ' + r['commit'][:12] + '. */\n'
       'const HK_RIG = ' + json.dumps({'names': r['names'], 'parents': r['parents'], 'avatars': av}, separators=(',', ':')) + ';\n')
open(os.path.join(os.path.dirname(HK), 'parts', 'hkrig.js'), 'w').write(out)
print('hkrig.js', len(out), 'bytes,', len(av), 'avatars')
